const char* deherm_dmsdk_borrowed_profile_name(uint16_t id) { return id < deherm_dmsdk_borrowed_count() ? kProfileNames[id] : "deherm.c-abi-native.unknown"; }
uint32_t deherm_dmsdk_borrowed_profile_contract_shape_count(void) { return UINT32_C(47); }
const char* deherm_dmsdk_borrowed_profile_contract_shape_name(uint16_t shape) { return shape < 47 ? kProfileContractShapeNames[shape] : "unknown"; }
